'use strict';
const fs = require('fs');
const readline = require('readline');
const path = require('path');

async function run() {
  const logFile = path.join(
    'C:', 'Users', 'SELIM', '.gemini', 'antigravity-ide', 'brain',
    '6c00a7a2-63e4-4080-9615-b66a8f1c02d1', '.system_generated', 'logs', 'transcript_full.jsonl'
  );

  if (!fs.existsSync(logFile)) {
    console.error('Log file does not exist at:', logFile);
    return;
  }

  console.log('Reading log file:', logFile);
  const fileStream = fs.createReadStream(logFile);
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity
  });

  for await (const line of rl) {
    if (line.includes('explorer-operational-tab-content')) {
      try {
        const obj = JSON.parse(line);
        if (obj.tool_calls) {
          console.log('\n--- FOUND TOOL CALL ---');
          console.log('Step Index:', obj.step_index);
          console.log('Type:', obj.type);
          obj.tool_calls.forEach(tc => {
            if (tc.arguments && tc.arguments.ReplacementContent) {
              console.log('ReplacementContent Length:', tc.arguments.ReplacementContent.length);
              console.log('Preview:');
              console.log(tc.arguments.ReplacementContent.substring(0, 1500));
            }
          });
        }
      } catch (err) {
        // ignore JSON parse error for partial lines
      }
    }
  }
}

run();
